create or replace view gov_repo.v_ai_system_risk_posture as select s.organisation_id,s.system_id,s.system_code,s.name as system_name,s.risk_class,s.residual_risk_level,s.lifecycle,s.cg_sys_005_risk_mgmt,s.risk_mgmt_last_review,s.risk_mgmt_next_review,(s.risk_mgmt_next_review<current_date and s.risk_mgmt_next_review is not null) as risk_review_overdue,s.bias_assessment_conducted,s.bias_assessment_date,s.fria_conducted,s.fria_date,(select count(*) from gov_repo.agents a where a.ai_system_id=s.system_id and a.status not in ('decommissioned')) as total_agents,(select count(*) from gov_repo.agents a where a.ai_system_id=s.system_id and a.risk_level='critical' and a.status not in ('decommissioned')) as critical_agents,(select count(*) from gov_repo.agents a where a.ai_system_id=s.system_id and a.risk_level='high' and a.status not in ('decommissioned')) as high_risk_agents,(select coalesce(sum(rp.financial_impact_eur),0) from gov_repo.agent_risk_propagation rp join gov_repo.agents a on a.agent_id=rp.risk_source_agent_id where a.ai_system_id=s.system_id and rp.is_active=true) as total_financial_exposure_eur,(select count(*) from gov_repo.agent_risk_propagation rp join gov_repo.agents a on a.agent_id=rp.risk_source_agent_id where a.ai_system_id=s.system_id and rp.criticality in ('critical','high') and rp.is_active=true) as critical_propagation_paths,s.serious_incidents_reported,s.last_serious_incident_at,(select count(*) from gov_repo.exceptions ex join gov_repo.agents a on a.agent_id=ex.agent_id where a.ai_system_id=s.system_id and ex.status='active') as active_exceptions,(select count(*) from gov_repo.risk_entries re where s.system_id=any(re.related_agent_ids::uuid[]) or exists(select 1 from gov_repo.agents a where a.ai_system_id=s.system_id and a.agent_id=any(re.related_agent_ids))) as open_risk_entries,u_owner.full_name as owner_name,u_ra.full_name as residual_risk_acceptor_name from gov_repo.ai_systems s left join gov_repo.governance_users u_owner on u_owner.user_id=s.owner_user_id left join gov_repo.governance_users u_ra on u_ra.user_id=s.residual_risk_accepted_by where s.status!='decommissioned' order by case s.risk_class when 'unacceptable' then 1 when 'high' then 2 when 'limited' then 3 else 4 end,case s.residual_risk_level when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,s.name;
create or replace function gov_repo.ai_system_compliance_gaps(p_organisation_id uuid)
returns table(system_id uuid,system_code varchar,system_name varchar,risk_class gov_repo.ai_act_risk_class,lifecycle gov_repo.ai_system_lifecycle,gap_registered boolean,gap_owner boolean,gap_risk_classified boolean,gap_tech_doc boolean,gap_risk_mgmt boolean,gap_human_oversight boolean,gap_conformity boolean,gap_post_market boolean,gap_eu_db boolean,gap_ce_marking boolean,gap_pms_plan boolean,gap_fria boolean,total_gaps integer,owner_name varchar,owner_email varchar)
language sql security definer as $$ select s.system_id,s.system_code,s.name,s.risk_class,s.lifecycle,not s.cg_sys_001_registered,not s.cg_sys_002_owner,not s.cg_sys_003_risk_classified,not s.cg_sys_004_tech_doc,not s.cg_sys_005_risk_mgmt,not s.cg_sys_006_human_oversight,not s.cg_sys_007_conformity,not s.cg_sys_008_post_market,(s.eu_ai_db_registered=false and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed')),(s.ce_marking_status not in ('marked','not_applicable') and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed')),(s.pms_plan_documented=false and s.lifecycle in ('production','post_market_surveillance')),(s.fria_conducted=false and s.risk_class='high' and s.annex_iii_sector in ('essential_services_benefits','employment_worker_management','law_enforcement','biometric_identification')),(case when not s.cg_sys_001_registered then 1 else 0 end+case when not s.cg_sys_002_owner then 1 else 0 end+case when not s.cg_sys_003_risk_classified then 1 else 0 end+case when not s.cg_sys_004_tech_doc then 1 else 0 end+case when not s.cg_sys_005_risk_mgmt then 1 else 0 end+case when not s.cg_sys_006_human_oversight then 1 else 0 end+case when not s.cg_sys_007_conformity then 1 else 0 end+case when not s.cg_sys_008_post_market then 1 else 0 end+case when s.eu_ai_db_registered=false and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed') then 1 else 0 end+case when s.ce_marking_status not in ('marked','not_applicable') and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed') then 1 else 0 end+case when s.pms_plan_documented=false and s.lifecycle in ('production','post_market_surveillance') then 1 else 0 end+case when s.fria_conducted=false and s.risk_class='high' and s.annex_iii_sector in ('essential_services_benefits','employment_worker_management','law_enforcement','biometric_identification') then 1 else 0 end),u.full_name,u.email from gov_repo.ai_systems s join gov_repo.governance_users u on u.user_id=s.owner_user_id where s.organisation_id=p_organisation_id and s.status not in ('decommissioned') and (not s.cg_sys_001_registered or not s.cg_sys_002_owner or not s.cg_sys_003_risk_classified or not s.cg_sys_004_tech_doc or not s.cg_sys_005_risk_mgmt or not s.cg_sys_006_human_oversight or not s.cg_sys_007_conformity or not s.cg_sys_008_post_market or (s.eu_ai_db_registered=false and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed')) or (s.ce_marking_status not in ('marked','not_applicable') and s.risk_class='high' and s.lifecycle in ('production','conformity_assessed')) or (s.pms_plan_documented=false and s.lifecycle in ('production','post_market_surveillance')) or (s.fria_conducted=false and s.risk_class='high' and s.annex_iii_sector in ('essential_services_benefits','employment_worker_management','law_enforcement','biometric_identification'))) order by case s.risk_class when 'unacceptable' then 1 when 'high' then 2 when 'limited' then 3 else 4 end,18 desc; $$;;
